from pathlib import Path
import json,hashlib,base64,shutil,asyncio
from playwright.async_api import async_playwright
R=Path(__file__).resolve().parents[1];OLD=R.parent/'map-battle-ui-b-v4'
names=['class_adventurer_portrait','class_ranger_portrait','class_spellblade_portrait','class_dragon_knight_portrait','monster_slime_portrait','monster_goblin_archer_portrait','monster_cave_troll_portrait','node_start','node_combat','node_unknown','item_small_potion','item_shield_potion','item_revival_stone']
rows=[]
for name in names+['battle_back','battle_mid','battle_ground','battle_front']:
    source=OLD/'assets'/('runtime' if name in names else 'layers')/(name+'.png');dest=R/'assets'/source.name
    shutil.copyfile(source,dest);rows.append(dict(id=name,file='assets/'+dest.name,source=str(source.relative_to(R.parent)),sha256=hashlib.sha256(dest.read_bytes()).hexdigest(),method='unchanged copy of v4 independent art'))
(R/'asset-manifest.json').write_text(json.dumps({'status':'glass-material-sample-awaiting-review','assets':rows},ensure_ascii=False,indent=2)+'\n')
def src(n):return 'data:image/png;base64,'+base64.b64encode((R/'assets'/(n+'.png')).read_bytes()).decode()
def pic(n,cls='',style=''):return f'<img class="{cls}" style="{style}" src="{src(n)}" alt="">'
def icon(name):
    paths={'focus':'<circle cx="12" cy="12" r="5"/><path d="M12 2v4m0 12v4M2 12h4m12 0h4"/>','overview':'<path d="M4 9V4h5m6 0h5v5M4 15v5h5m6 0h5v-5"/>','minus':'<path d="M5 12h14"/>','plus':'<path d="M5 12h14M12 5v14"/>','sun':'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M20 4l-2 2M6 18l-2 2"/>','clock':'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'}
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+paths[name]+'</svg>'
units=[('P1','class_adventurer_portrait','12/12',''),('P2','class_ranger_portrait','18/18',''),('P3','class_spellblade_portrait','20/24','active'),('P4','class_dragon_knight_portrait','32/32',''),('P5','class_adventurer_portrait','0/12','down'),('P6','class_ranger_portrait','9/18','next'),('P7','class_dragon_knight_portrait','32/32',''),('M1','monster_slime_portrait','8/8','enemy'),('M2','monster_goblin_archer_portrait','12/12','enemy'),('M3','monster_cave_troll_portrait','48/48','enemy')]
def actor(i,x,y,cls=''):
    id,asset,hp,state=units[i];return f'<div class="actor {state} {cls}" style="left:{x}px;top:{y}px">'+pic(asset,'body')+f'<span class="unit-id">{id}</span>'+('<span class="cross">×</span>' if state=='down' else '<span class="next-mark">◷</span>' if state=='next' else '')+f'<div class="unit-hud"><span class="hp">♥ {hp}</span><span class="shield">◇ 0</span></div></div>'
mapart='<svg class="roads" viewBox="0 0 960 480"><path d="M180 230H575L890 -100M575 230l350 330"/><path class="centerline" d="M180 230H575L890 -100M575 230l350 330"/><ellipse cx="575" cy="276" rx="144" ry="112"/></svg>'
mapart+=pic('node_start','node','left:100px;top:115px')+pic('node_combat','node','left:495px;top:115px')
mapart+='<span class="node-label camp">1 · 营地</span><span class="node-label junction">2 · 森林路口</span><span class="direction-label upper">3 · 弓手哨点 ↗</span><span class="direction-label lower">4 · 未探索地点4 ↘</span>'
