px #235a6422}.map-unit.enemy span{color:#9b5348}.map-unit.active:before{content:"";position:absolute;top:0;left:42px;width:12px;height:9px;background:#176a86;clip-path:polygon(0 0,100% 0,50% 100%)}.map-unit b{position:absolute;right:1px;bottom:22px;color:#ad524b;font-size:28px}.map-unit.next b{color:#355365}.battle{position:relative;background:#ffffff66}.scene{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.9}.scene.front{z-index:4;opacity:.65;pointer-events:none}.battle-heading{z-index:10;position:absolute;left:22px;top:18px;padding:8px 15px;font-size:27px;font-weight:700;background:#ffffffe0;backdrop-filter:blur(22px);border-radius:16px}.actor{position:absolute;width:126px;height:176px;z-index:5;text-align:center}.actor:before{content:"";position:absolute;left:30px;top:91px;width:65px;height:12px;background:#26473b25;border-radius:50%;filter:blur(2px)}.actor .body{position:absolute;top:0;left:9px;width:108px;height:104px;object-fit:contain}.unit-id{position:absolute;top:97px;left:43px;font-size:24px;font-weight:700;color:#376273;line-height:28px}.enemy .unit-id{color:#9b5348}.unit-hud{position:absolute;top:129px;left:0;width:126px;display:flex;justify-content:center;gap:9px;align-items:center;padding:3px 5px;font-size:24px;border-radius:13px;background:#ffffffbe;backdrop-filter:blur(14px);border:1px solid #ffffffe3;white-space:nowrap;line-height:30px}.actor:not(.enemy) .unit-hud{flex-direction:column;gap:0;top:127px;padding:0 6px;line-height:26px}.actor.enemy .body{width:86px;height:80px;left:20px}.actor.enemy:before{top:75px}.actor.enemy .unit-id{top:82px}.actor.enemy .unit-hud{top:112px}.actor.active:after{content:"";position:absolute;top:90px;left:22px;width:84px;height:16px;border:2px solid #387d91;border-radius:50%}.cross,.next-mark{position:absolute;top:93px;right:8px;font-size:30px;color:#ad524b;z-index:8}.next-mark{color:#476579}.track{padding:5px 34px}.track-line{position:absolute;left:76px;right:76px;top:45px;height:9px;background:#8cafbc52;border-radius:8px;border:1px solid #ffffff9b;box-shadow:inset 0 2px 2px #54758217}.track-line:before{content:"";position:absolute;left:0;top:0;width:33.3%;height:100%;border-radius:8px;background:linear-gradient(90deg,#508aa0,#287691)}.queue{position:relative;display:flex;justify-content:space-between;align-items:start}.queue-unit{width:80px;position:relative;text-align:center;padding-top:7px}.avatar{width:64px;height:64px;margin:auto;border-radius:50%;background:linear-gradient(130deg,#ffffffdf,#f6fcff7d);border:1px solid white;box-shadow:0 3px 9px #1c4c6117,inset 0 2px 2px white}.avatar img{width:60px;height:60px;object-fit:contain}.queue-id{font-size:24px;font-weight:600;line-height:28px;display:block;color:#3f6476}.queue-unit.active .avatar{box-shadow:0 0 0 3px #4d8599,inset 0 2px 2px white,0 4px 16px #54849432}.queue-unit.active:before{content:"";position:absolute;top:-6px;left:34px;width:12px;height:9px;background:#176a86;clip-path:polygon(0 0,100% 0,50% 100%)}.queue-state,.queue-clock{position:absolute;right:0;top:3px;background:#f8ffff;border:1px solid white;border-radius:50%;height:24px;width:24px;font-size:19px;line-height:22px;color:#32738a;box-shadow:0 2px 6px #56768422}.queue-clock{font-size:25px;color:#44606c}.queue-cross{position:absolute;top:14px;left:19px;color:#b75c57;font-size:42px;font-weight:700}.deck{padding:14px 16px;display:flex;flex-direction:column;gap:12px}.skills{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.skill{position:relative;height:140px;padding:11px 18px;background:linear-gradient(145deg,#ffffff91,#eef7f761);border-radius:18px;border:1px solid #ffffffa6;backdrop-filter:blur(16px);box-shadow:inset 0 1px 0 #ffffffd6}.skill-title{display:flex;justify-content:space-between;align-items:center;font-size:26px;line-height:34px}.skill-title strong{font-size:29px}.skill-title span{font-size:24px;color:#507181}.skill-target,.skill-effect{font-size:24px;line-height:30px}.skill-target{color:#446779;margin-top:2px}.skill-effect{max-width:490px}.reason{position:absolute;right:18px;bottom:9px;font-size:24px;color:#9d6659}.available{color:#367c83}.inventory{display:grid;grid-template-columns:144px repeat(3,1fr);gap:16px;align-items:center;min-height:64px}.inventory-label{font-size:26px;font-weight:600;padding-left:7px}.item{display:flex;align-items:center;gap:11px}.item img{width:48px;height:48px;object-fit:contain}.item strong{font-size:26px;font-weight:600}.item strong span{font-size:25px;color:#496d7e;font-weight:400}.item p{font-size:24px;line-height:29px;margin:0;color:#547384}button:focus-visible{outline:3px solid #176a86;outline-offset:4px}body.reduced-transparency .frost,body.reduced-transparency .liquid{background:#f6fbfb;backdrop-filter:none}'''
doc='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>晴空学园 · 玩家战斗玻璃材质样稿</title><style>'+css+'</style><body><div class="ambient" style="--environment:url('+src('battle_back')+')"></div><main class="shell"><header class="header frost"><div class="seal liquid">'+icon('sun')+'</div><div class="heading"><div class="eyebrow">PVE · 玩家回合</div><div class="name">晨曦森林守护者小队长安然</div></div><div class="resources"><span class="hp">♥ 20/24</span><span class="shield">◇ 0</span><span>◉ 0</span><span>★ 0</span><span class="team">● 蓝队</span></div><div class="timer"><span class="round">第1轮 · 已暂停</span><strong>剩余 17 秒</strong></div></header><div class="main"><section class="map frost"><div class="panel-heading">森林路口 · 地图</div><div class="map-actions">'+''.join('<button class="liquid" aria-label="'+label+'">'+icon(n)+'</button>' for n,label in [('focus','回到行动者'),('overview','地图总览'),('minus','缩小'),('plus','放大')])+'</div>'+mapart+'<span class="map-foot">镜头：跟随战斗节点</span></section><section class="battle frost">'+fight+'<div class="battle-heading">森林路口 · 同节点战斗</div></section></div><section class="track frost"><div class="track-line"></div><div class="queue">'+q+'</div></section><section class="deck frost"><div class="skills">'+cards+'</div><div class="inventory"><span class="inventory-label">个人物品</span>'+items+'</div></section></main></body></html>'
(R/'previews/player_battle_glass_16x9.html').write_text(doc)
(R/'sources/materials.css').write_text(css+'\n')
async def export():
    async with async_playwright() as p:
        b=await p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=await b.new_page(viewport={'width':1920,'height':1080},device_scale_factor=1)
        await page.set_content(doc);await page.evaluate('document.fonts.ready');await page.screenshot(path=str(R/'previews/player_battle_glass_16x9.png'))
        report=await page.evaluate('''()=>({canvas:[innerWidth,innerHeight],frostPanels:document.querySelectorAll('.frost').length,liquidButtons:[...document.querySelectorAll('button')].map(e=>({label:e.ariaLabel,glass:e.classList.contains('liquid'),w:e.offsetWidth,h:e.offsetHeight})),skillCards:document.querySelectorAll('.skill').length,queueUnits:document.querySelectorAll('.queue-unit').length,overflow:[...document.querySelectorAll('.name,.resources,.skill-effect,.item')].filter(e=>e.scrollWidth>e.clientWidth+1).map(e=>e.className)})''')
        assert not report['overflow'],report
        assert len(report['liquidButtons'])==4 and all(b['glass'] for b in report['liquidButtons'])
        assert report['queueUnits']==10
        (R/'validation.json').write_text(json.dumps({'status':'pass','browserOnly':True,'nativeMaterialVerified':False,'artApproved':False,**report},ensure_ascii=False,indent=2)+'\n');await b.close()
asyncio.run(export());print('Exported one 1920x1080 sample; glass buttons and 10-unit queue checked.')
